from kubernetes import client, config
config.load_kube_config()
_apps = client.AppsV1Api()
_autoscaling = client.AutoscalingV1Api()

def _validated_replicas(replicas: int) -> int:
    if replicas < 0:
        raise ValueError('replicas must be zero or greater')
    return int(replicas)

def _remove_hpas_when_scaled_to_zero(namespace: str, deployment: str, count: int) -> list:
    # An HPA targeting the Deployment would scale it back up, so delete it when scaling to zero.
    if count != 0:
        return []
    removed = []
    for hpa in _autoscaling.list_namespaced_horizontal_pod_autoscaler(namespace=namespace).items:
        ref = hpa.spec.scale_target_ref
        if ref.kind == 'Deployment' and ref.name == deployment:
            _autoscaling.delete_namespaced_horizontal_pod_autoscaler(name=hpa.metadata.name, namespace=namespace)
            removed.append(hpa.metadata.name)
    return removed

def set_deployment_replicas(namespace: str, deployment: str, replicas: int) -> dict:
    count = _validated_replicas(replicas)
    current = _apps.read_namespaced_deployment_scale(name=deployment, namespace=namespace)
    previous = current.spec.replicas
    removed_hpas = _remove_hpas_when_scaled_to_zero(namespace, deployment, count)
    updated = _apps.patch_namespaced_deployment_scale(name=deployment, namespace=namespace, body={'spec': {'replicas': count}})
    return {'deployment': deployment, 'namespace': namespace, 'previous': previous, 'replicas': updated.spec.replicas, 'removed_hpas': removed_hpas}
